-- ============================================================================================
-- Schema drift fix: columns/tables mapped by entities but never created in Neon.
--
-- Generated by diffing the entity model against the production database (Hibernate
-- schema-generation "update" script, not executed by Hibernate). Without these:
--   chat_messages.client_message_id  -> every chat message query fails (messages not loading)
--   notifications.actor_id           -> every notification insert fails, rolling back whatever
--                                       sent it (music approve/reject, follows, likes, ...)
--   transactions.*                   -> wallet history / dashboard stats / payments fail
--   music_plays                      -> release detail (play counts) fails: "Song not found"
--
-- Every statement is idempotent; running the file twice is safe. No data is deleted.
-- ============================================================================================

ALTER TABLE IF EXISTS chat_messages ADD COLUMN IF NOT EXISTS client_message_id VARCHAR(64);

CREATE TABLE IF NOT EXISTS music_plays (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    duration_seconds INTEGER,
    played_at        TIMESTAMP(6) NOT NULL,
    release_id       BIGINT NOT NULL REFERENCES music_releases(id),
    track_id         BIGINT REFERENCES music_tracks(id),
    user_id          BIGINT REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_music_plays_release ON music_plays (release_id);
CREATE INDEX IF NOT EXISTS idx_music_plays_user ON music_plays (user_id);
CREATE INDEX IF NOT EXISTS idx_music_plays_played_at ON music_plays (played_at);

ALTER TABLE IF EXISTS notifications ADD COLUMN IF NOT EXISTS actor_id BIGINT REFERENCES users(id);

ALTER TABLE IF EXISTS transactions ADD COLUMN IF NOT EXISTS after_balance NUMERIC(38,2);
ALTER TABLE IF EXISTS transactions ADD COLUMN IF NOT EXISTS before_balance NUMERIC(38,2);
ALTER TABLE IF EXISTS transactions ADD COLUMN IF NOT EXISTS currency VARCHAR(10);
ALTER TABLE IF EXISTS transactions ADD COLUMN IF NOT EXISTS external_reference VARCHAR(100);
ALTER TABLE IF EXISTS transactions ADD COLUMN IF NOT EXISTS phone_number VARCHAR(50);
ALTER TABLE IF EXISTS transactions ADD COLUMN IF NOT EXISTS provider VARCHAR(50);
ALTER TABLE IF EXISTS transactions ADD COLUMN IF NOT EXISTS reference VARCHAR(100);
